WITH src AS (SELECT *, DATE_SUB(end_date, 6) AS end_date_minus_6d FROM subscriptions WHERE customer_id IN (16, 27) OR monthly_fee BETWEEN 90 AND 240), plan_summary AS (SELECT plan, ROUND((100 * SUM(CASE WHEN status = 'PAUSED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_paused, AVG(monthly_fee) AS avg_monthly_fee FROM src GROUP BY plan) SELECT * FROM plan_summary WHERE avg_monthly_fee < 70 ORDER BY pct_paused, plan LIMIT 5;
